'use strict';
// The NEGATIVE control for the override above: a receiver whose STATIC
// type is the base and whose runtime class the compiler cannot pin.
//
// An untyped parameter binds the caller's argument type, so an ordinary
// untyped forwarder monomorphizes per receiver class and always resolves
// exactly — that is why mysql2's own `pool.releaseConnection(conn)` chain
// compiles. A JSDoc-DECLARED parameter is the opposite: the type is
// written down as the base, the argument at the call could be any
// subclass, and generic methods own no vtable slot to sort that out at run
// time. The call must refuse by name, not silently reach the base body.
const { Base } = require('./index.js');

/**
 * @param {Base} conn
 * @param {*} cb
 */
function endThroughBase(conn, cb) {
  return conn.end(cb);
}

exports.endThroughBase = endThroughBase;
exports.Base = Base;
